insert into public.settings (key, value) values ('hero', '{"tagline": "Metal sinfónico · Patagonia", "title": "Desde Neuquén, al borde del Kósmos.", "image": "assets/img/live-stage-blue.webp", "video": "", "cta_primary_label": "Escuchar", "cta_primary_url": "musica.html", "cta_secondary_label": "Tienda oficial", "cta_secondary_url": "tienda.html"}'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.settings (key, value) values ('bio', '{"short": "Elessär nace en julio de 2007 en Neuquén, en la Patagonia argentina. Metal sinfónico de composición propia, con arreglos orquestales y melodías que miran a la gran tradición europea del género sin dejar de sonar a este lado del mundo.", "long": ["Elessär nace en julio de 2007 en Neuquén, en la Patagonia argentina, con una idea clara: hacer metal sinfónico de composición propia, con arreglos orquestales y melódicos que dialogan con la escuela europea del género.", "En 2013 la banda edita Dark Desires, su primer disco. El trabajo recibe reseñas muy positivas en medios especializados de Bélgica, Inglaterra y Estados Unidos, entre otros países, y lleva el nombre de Elessär más allá de la Patagonia.", "En 2019 llega Kósmos, su primer álbum conceptual. Si el cosmos suele pensarse como el universo exterior, aquí la mirada se vuelve hacia adentro: el autoconocimiento y la introspección como otra forma de orden y armonía, hasta el punto en que se disuelve la distinción entre el mundo y el yo.", "Con reconocimientos a nivel nacional e internacional, la banda sigue explorando territorios propios, como su reinterpretación de «Por una cabeza», el clásico de Carlos Gardel, llevado al lenguaje del metal sinfónico."], "timeline": [{"year": "2007", "text": "Formación de la banda en Neuquén, Patagonia argentina."}, {"year": "2013", "text": "Dark Desires, primer disco. Reseñas en medios de Bélgica, Inglaterra y EE. UU."}, {"year": "2019", "text": "Kósmos, primer álbum conceptual: doce piezas sobre el universo interior."}, {"year": "2023", "text": "Décimo aniversario del ciclo Capital Acústica, Museo Nacional de Bellas Artes de Neuquén."}, {"year": "Hoy", "text": "«Por una cabeza» (C. Gardel) en versión Elessär, y nuevas canciones en camino."}], "image": "assets/img/band-promo.webp"}'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.settings (key, value) values ('socials', '{"spotify": "https://open.spotify.com/artist/3Q89babzF4j6t0kP7gfUL6", "youtube": "https://www.youtube.com/channel/UCDrV_jh5gi7aL-ciIQqId9w", "bandcamp": "https://elessarband.bandcamp.com/", "instagram": "", "facebook": "", "tiktok": ""}'::jsonb) on conflict (key) do update set value = excluded.value;
