insert into public.settings (key, value) values ('shop', '{"shipping_options": [{"id": "pickup", "label": "Retiro en Neuquén capital", "description": "Coordinamos por mail o WhatsApp", "price": 0}, {"id": "national", "label": "Envío a todo el país", "description": "Correo Argentino / Andreani · 3 a 7 días hábiles", "price": 6500}], "note": "Los pedidos se despachan dentro de las 72 h hábiles de acreditado el pago."}'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.settings (key, value) values ('press', '{"title": "Kit de prensa", "text": "Biografía, discografía, fotos y logos en alta para medios, productores y festivales.", "downloads": [{"label": "EPK completo (PDF)", "url": "assets/epk/elessar-epk.pdf"}, {"label": "Logo · PNG transparente", "url": "assets/img/logo.png"}, {"label": "Foto promocional", "url": "assets/img/band-promo.webp"}, {"label": "Foto en vivo", "url": "assets/img/live-vocal-logo.webp"}]}'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.settings (key, value) values ('payments', '{"mercadopago_enabled": true, "mercadopago_label": "MercadoPago", "mercadopago_description": "Tarjetas de crédito y débito, dinero en cuenta, efectivo.", "paypal_enabled": false, "paypal_label": "PayPal", "paypal_description": "Pagos desde el exterior. Se cobra en dólares (USD).", "paypal_usd_rate": null, "stripe_enabled": false, "stripe_label": "Tarjeta internacional (Stripe)", "stripe_description": "Visa, Mastercard, Amex — pagos desde el exterior.", "whatsapp_enabled": false, "whatsapp_number": "", "whatsapp_label": "Coordinar por WhatsApp", "whatsapp_description": "Te abrimos WhatsApp con tu pedido y coordinamos pago y entrega.", "whatsapp_intro": "Hola Elessär, estoy en la página y quiero comprar los siguientes productos:", "whatsapp_include_total": true, "whatsapp_cart_button": true}'::jsonb) on conflict (key) do update set value = excluded.value;
