insert into public.releases (slug, title, type, year, cover_url, description, spotify_url, bandcamp_album_id, bandcamp_url, youtube_url, tracks, sort, published) values ('por-una-cabeza', 'Por una cabeza', 'Single', 2024, 'assets/img/cover-por-una-cabeza.webp', 'El tango de Carlos Gardel y Alfredo Le Pera, reimaginado con orquesta, guitarras y la voz de Elessär. Un puente entre el Río de la Plata y la tradición sinfónica.', 'https://open.spotify.com/artist/3Q89babzF4j6t0kP7gfUL6', null, '', 'https://www.youtube.com/channel/UCDrV_jh5gi7aL-ciIQqId9w', '["Por una cabeza (C. Gardel)"]'::jsonb, 1, true) on conflict (slug) do nothing;
insert into public.releases (slug, title, type, year, cover_url, description, spotify_url, bandcamp_album_id, bandcamp_url, youtube_url, tracks, sort, published) values ('kosmos', 'Kósmos', 'Álbum', 2019, 'assets/img/cover-kosmos.webp', 'El primer álbum conceptual de la banda. Para los antiguos griegos, κόσμος nombraba la armonía y el orden del universo. Kósmos propone el viaje inverso: hacia adentro, hacia el autoconocimiento, hasta que se borra la frontera entre el mundo y el yo.', 'https://open.spotify.com/artist/3Q89babzF4j6t0kP7gfUL6', '2029945776', 'https://elessarband.bandcamp.com/album/k-smos', 'https://www.youtube.com/channel/UCDrV_jh5gi7aL-ciIQqId9w', '["Ultimate Escape", "Impetus", "Introducing the Majestic", "Afraid", "Eternity", "Kósmos", "Inside", "The Way", "What precedes us", "Be Still", "Truth", "Inside the Kósmos"]'::jsonb, 2, true) on conflict (slug) do nothing;
insert into public.releases (slug, title, type, year, cover_url, description, spotify_url, bandcamp_album_id, bandcamp_url, youtube_url, tracks, sort, published) values ('dark-desires', 'Dark Desires', 'Álbum', 2013, 'assets/img/cover-dark-desires.webp', 'El disco debut. Gótico, melódico y orquestal, recibió reseñas muy positivas en medios especializados de Bélgica, Inglaterra y Estados Unidos.', 'https://open.spotify.com/artist/3Q89babzF4j6t0kP7gfUL6', null, 'https://elessarband.bandcamp.com/', 'https://www.youtube.com/channel/UCDrV_jh5gi7aL-ciIQqId9w', '[]'::jsonb, 3, true) on conflict (slug) do nothing;
